"""Count number of vulnerabilities in depscan output.

    Args:
        data (str): String representation of depscan "json" output

    Returns:
        [high, med, low]: Number of high/med/low severity vulnerabilities
    """
def count_vulns(data: Any) -> object {
    high = data.count('"severity": "HIGH"');
    high += data.count('"severity": "CRITICAL"');
    med = data.count('"severity": "MEDIUM"');
    low = data.count('"severity": "LOW"');
    return (high, med, low);
}

"""
    Converts RGB to GrayScale using luminosity method
    :param r: red value (from 0.0 to 1.0)
    :param g: green value (from 0.0 to 1.0)
    :param b: blue value (from 0.0 to 1.0)
    :return GreyScale value (from 0.0 to 1.0)
    """
def rgbToGray(r: Any, g: Any, b: Any) -> object {
    g = (0.21 * r) + (0.72 * g) + (0.07 * b);
    return g;
}

